function parse(tokens) {
  let p = 0;
  const peek = () => tokens[p];
  const next = () => tokens[p++];

  function expr()   { return binop(addsub, ['<']); }      // 가장 낮은 우선순위
  function addsub() { return binop(term, ['+','-']); }
  function term()   { return binop(primary, ['*','/']); }  // 높은 우선순위
  function primary() {
    if (peek().v === '(') { next(); const e = expr(); expect(')'); return e; }  // 재귀
    return { node: 'num', val: next().v };
  }
  function binop(higher, ops) {
    let left = higher();
    while (ops.includes(peek().v)) { const op = next().v; left = { node: op, l: left, r: higher() }; }
    return left;
  }
  const ast = expr();
  expect('eof');   // 마지막에 eof (6장)
  return ast;
}

// 왼쪽 결합: 반복(while)으로 왼쪽에 쌓는다 → (a-b)-c  ✅ 보통 원하는 것
function addsub() {
  let left = term();
  while (['+','-'].includes(peek().v)) {
    const op = next().v;
    left = { node: op, l: left, r: term() };   // left 에 계속 쌓음
  }
  return left;
}
// 오른쪽 결합: 재귀로 오른쪽에 붙인다 → a^(b^c)  (거듭제곱·대입)
function power() {
  const left = primary();
  if (peek().v === '^') { next(); return { node:'^', l:left, r: power() }; }  // 재귀
  return left;
}
